insert or replace into sops (id, section, domain, title, body, version, restricted, status, keywords) values ('culture', 'Start Here', NULL, 'Culture & Conduct', '[{"t":"p","x":"The 5 Pillars are how we think. The Doctrine is how we operate. The Redlines are what ends employment. Leaders included: lead by example."},{"t":"h2","x":"The 5 Pillars"},{"t":"table","head":["Pillar","In short"],"rows":[["Ownership Mentality","Own your tasks and outcomes. No excuses, no blame, finish what you start."],["Progress Over Perfection","Move and deliver fast, then improve on real feedback. Done beats drafted."],["Data-Driven Thinking","Decide on numbers and clear reasoning, not assumptions or feelings."],["Continuous Growth","Get a little better every week. Learn from mistakes, build better habits."],["Team Before Ego","Put team success above personal ego. No gossip, no politics, open to feedback."]]},{"t":"h2","x":"Company Doctrine"},{"t":"steps","ordered":false,"x":["Company comes first","Ownership over excuses","System over individuals","Loyalty and trust are earned","Discipline creates freedom","Data over assumption","Leaders lead by example","Improve every month","No toxic behavior","Build something bigger"]},{"t":"h2","x":"Redlines — zero tolerance"},{"t":"callout","tone":"warn","title":"Immediate termination","x":"Data betrayal · Player or financial misconduct · Theft or fraud · Unauthorized player handling · Security violations · Dishonesty with leadership · External business conflicts · Substance abuse on duty · Public defamation · Unauthorized contact with ex-staff."}]', 'V1.0', 0, 'live', 'pillars doctrine redlines values conduct ownership integrity');
