insert or replace into sops (id, section, domain, title, body, version, restricted, status, keywords) values ('grace', 'SOP Book', 'Money Control & Bonuses', 'Grace Period List', '[{"t":"h2","x":"Objective"},{"t":"p","x":"Filter eligible Grace Period players and send targeted Internal Mail to re-engage them before the grace window expires. First daily task, once the feed lands."},{"t":"h2","x":"Sending schedule"},{"t":"table","head":["Day","Action"],"rows":[["Monday","Grace Period Player IM (List A)"],["Tuesday","Potential Player IM (List B)"],["Thursday","Follow-up List A"],["Friday","Follow-up List B"],["Wed / Sat / Sun","No Grace IM"]]},{"t":"h2","x":"Procedure"},{"t":"steps","x":["Receive the Grace Period database from Retention Admin (Handover tab).","Copy into the Customer Approaching Lark Base, Grace Period (Day). Paste values only.","Filter Valid vs Invalid by brand and status.","Valid: pass list to Admin for SMS, CS sends IM + Push. Invalid: IM + Push only, no bonus mention.","Update the QA Record with a BO screenshot."]},{"t":"h2","x":"Bonus ladder"},{"t":"table","head":["Tier","Deposit","Free bonus","Cap"],"rows":[["T3","RM 100","RM 18","SW × 20%"],["T3","RM 500","RM 58","SW × 20%"],["TV","RM 600","RM 68","SW × 20%"],["TV","RM 900","RM 98","SW × 20%"]]},{"t":"callout","tone":"good","title":"Guardrails","x":"Contact before any deposit credit. Never contact HEALTHY or WATCH players. Counts are weighted, never a simple average."}]', 'V1.0', 0, 'live', 'bonus deposit grace expiry re-engage internal mail day shift');
