insert or replace into sops (id, section, domain, title, body, version, restricted, status, keywords) values ('ltv', 'SOP Book', 'Engagement Outreach', 'LTV List', '[{"t":"h2","x":"Objective"},{"t":"p","x":"Approach selected LTV players for targeted retention via Internal Mail. Top 70 LTV pool split into 10 players per day, Monday to Sunday."},{"t":"h2","x":"Procedure"},{"t":"steps","x":["Open the Handover tab, take today''s 10-player batch. Use today''s exact day.","Deduplicate: remove anyone already given Daily P&L or this week’s LTV.","Per-player check: not given this week, active, SW sufficient (bonus ≤ SW × 40%).","Trigger interaction, player must engage before issuance.","On target, submit Lark ticket (VVIP LTV 70 BONUS). Tag and update the QA Record."]},{"t":"h2","x":"Bonus ladder"},{"t":"table","head":["LTV","Free bonus","Cap"],"rows":[["2,000","RM 28","SW × 40%"],["10,000","RM 118","SW × 40%"],["20,000","RM 228","SW × 40%"],["≥ 21,000","RM 288","SW × 40% · cap"]]},{"t":"callout","tone":"good","title":"Guardrails","x":"Exactly 10 players a day, never carry over. SW × 40% hard cap. CS prepares the list; Admin sends the SMS."}]', 'V1.0', 0, 'live', 'bonus loyalty lifetime value top 70 retention');
insert or replace into sops (id, section, domain, title, body, version, restricted, status, keywords) values ('pnl', 'SOP Book', 'Engagement Outreach', 'Top PNL', '[{"t":"h2","x":"Objective"},{"t":"p","x":"Top 10 highest-loss players today get tiered Free Bonus compensation, capped at SW × 40%. Night Shift; export at 7:00 PM, engage at 8:00 PM."},{"t":"h2","x":"Eligibility (all must pass)"},{"t":"table","head":["Check","Pass"],"rows":[["Daily P&L","Negative (lost today)"],["Today’s reward","Not yet claimed"],["Secret Wallet","Bonus ≤ SW × 40%"],["Monthly P&L","Negative overall"]]},{"t":"callout","tone":"good","title":"Guardrails","x":"Sort loss high to low. SW × 40% is the hard cap. If Monthly P&L is profitable, no bonus (over-issuance exception)."}]', 'V1.0', 0, 'live', 'loss compensation night bonus pnl p&l biggest loser');
